// OUI (first three MAC octets) → vendor name.
//
// Data: `data/oui.txt`, generated by `data/build-oui.ts` from Wireshark's `manuf`
// file (itself built from the public IEEE MA-L registry). ~40k 24-bit blocks,
// legal suffixes stripped ("Sonos, Inc." → "Sonos"). Loaded lazily on first use.

import { readFileSync } from 'node:fs'

import { isRandomizedMac, normalizeMac } from './identity.ts'

const DATA_URL = new URL('./data/oui.txt', import.meta.url)

let table: Map<string, string> | undefined

/** Parse the `vendor\tOUI OUI …` format. Exported for tests. */
export function parseOuiTable(text: string): Map<string, string> {
  let map = new Map<string, string>()
  for (let line of text.split('\n')) {
    let tab = line.indexOf('\t')
    if (tab <= 0) continue
    let vendor = line.slice(0, tab)
    for (let oui of line.slice(tab + 1).split(' ')) if (oui) map.set(oui, vendor)
  }
  return map
}

function load(): Map<string, string> {
  if (!table) {
    try {
      table = parseOuiTable(readFileSync(DATA_URL, 'utf8'))
    } catch (error) {
      console.error('oui: failed to load vendor table', error)
      table = new Map()
    }
  }
  return table
}

/**
 * Vendor for a MAC address, or undefined when unknown. Always undefined for
 * locally administered (randomized) MACs, where the prefix means nothing.
 */
export function lookupVendor(mac: string): string | undefined {
  let norm = normalizeMac(mac)
  if (!norm || isRandomizedMac(norm)) return undefined
  // Multicast / broadcast addresses aren't devices.
  if (Number.parseInt(norm.slice(0, 2), 16) & 0x01) return undefined
  return load().get(norm.slice(0, 8).replace(/:/g, '').toUpperCase())
}
